<div class="adminhead"><h1>ارسال‌های کتاب</h1><a href="/admin">داشبورد</a></div><?php foreach($rows as $r):?><div class="submission"><h3><?=e($r['book_title'])?></h3><p>ارسال‌کننده: <?=e($r['submitter_name'])?> | <?=e($r['email'])?></p><p><?=nl2br(e($r['description']))?></p><form method="post" action="/admin/submission/status"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option <?=($r['status']=='pending'?'selected':'')?>>pending</option><option <?=($r['status']=='approved'?'selected':'')?>>approved</option><option <?=($r['status']=='edited'?'selected':'')?>>edited</option><option <?=($r['status']=='rejected'?'selected':'')?>>rejected</option></select><input name="admin_note" value="<?=e($r['admin_note']??'')?>" placeholder="یادداشت مدیریت"><button>ذخیره وضعیت</button></form></div><?php endforeach;?>
